'use client';
import { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { useAuth } from '@/lib/auth-context';
import { Download } from 'lucide-react';

const API = process.env.NEXT_PUBLIC_API_BASE ?? 'http://127.0.0.1:5000';

const C = {
  blue: '#155DFC', blueBg: '#EFF6FF', pageBg: '#F8F9FC', border: '#E2E8F0',
  textMain: '#101828', textSub: '#4A5565', textMuted: '#64748B', textDark: '#1E293B',
};

const PAGE_SIZE = 50;

interface PaginatedResponse {
  rows: ReportRow[]; page: number; page_size: number; total: number; total_pages: number;
  requester_country?: string | null;
}

interface ReportRow {
  id: string; emp_id: string | null; full_name: string; role: string;
  organisational_unit: string; h1_score: number | null; h2_score: number | null; talent_block: string | null;
}

// pms_year is the end year (e.g. 2026 = FY 2025/26)
function fiscalYear(y: number) { return `${y - 1}/${String(y).slice(-2)}`; }
function fiscalH1(y: number)   { return `H1 ${y - 1}/${String(y).slice(-2)}`; }
function fiscalH2(y: number)   { return `H2 ${y - 1}/${String(y).slice(-2)}`; }

function formatRole(role: string) {
  return ({ country_admin:'Country Admin', branch_admin:'Branch Admin', dept_admin:'Dept Admin',
            sub_dept_admin:'Sub-Dept Admin', employee:'Employee' } as Record<string,string>)[role] ?? role;
}

function TalentBadge({ value }: { value: string | null }) {
  if (!value) return <span style={{ color:'#CBD5E1', fontSize:12 }}>—</span>;
  const m: Record<string,{bg:string;color:string;label:string}> = {
    H:{bg:'#DCFCE7',color:'#166534',label:'High'},
    M:{bg:'#FEF9C3',color:'#854D0E',label:'Medium'},
    L:{bg:'#FEE2E2',color:'#991B1B',label:'Low'},
  };
  const s = m[value] ?? {bg:'#F1F5F9',color:'#475569',label:value};
  return <span style={{display:'inline-block',padding:'2px 10px',borderRadius:999,fontSize:11.5,fontWeight:600,background:s.bg,color:s.color}}>{s.label}</span>;
}

function Score({ value }: { value: number | null }) {
  if (value == null) return <span style={{color:'#CBD5E1',fontSize:12}}>—</span>;
  return <span style={{fontWeight:600,color:C.textDark,fontVariantNumeric:'tabular-nums',fontSize:13}}>{value.toFixed(2)}</span>;
}

async function handlePdfDownload(userId: string, year: number, countryName: string | null) {
  const res = await fetch(`${API}/api/workforce-report/all?pms_year=${year}&requester_id=${userId}`);
  if (!res.ok) throw new Error('Failed to fetch report data');
  const data = await res.json();
  const allRows: ReportRow[] = data.rows ?? data;

  const talentLabel = (v: string|null) =>
    v === 'H' ? 'High' : v === 'M' ? 'Medium' : v === 'L' ? 'Low' : '—';

  const tableRows = allRows.map((r, i) =>
    '<tr>' +
    '<td class="n">' + (i + 1) + '</td>' +
    '<td class="eid">' + (r.emp_id ?? '—') + '</td>' +
    '<td><div class="nm">' + r.full_name + '</div><div class="rl">' + formatRole(r.role) + '</div></td>' +
    '<td class="loc">' + r.organisational_unit + '</td>' +
    '<td class="r">' + (r.h1_score != null ? '<span class="sc">' + r.h1_score.toFixed(2) + '</span>' : '<span class="dash">—</span>') + '</td>' +
    '<td class="r">' + (r.h2_score != null ? '<span class="sc">' + r.h2_score.toFixed(2) + '</span>' : '<span class="dash">—</span>') + '</td>' +
    '<td class="r">' + (r.talent_block ? '<span class="badge b' + r.talent_block + '">' + talentLabel(r.talent_block) + '</span>' : '<span class="dash">—</span>') + '</td>' +
    '</tr>'
  ).join('');

  const LOGO = 'data:image/png;base64,';

  const css = [
    '@import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap\');',
    '*{box-sizing:border-box;margin:0;padding:0}',
    'html,body{background:#e0e0e0;font-family:Inter,Arial,sans-serif;color:#1E293B}',
    '.page{background:#fff;width:210mm;min-height:297mm;margin:8mm auto;box-shadow:0 4px 24px rgba(0,0,0,0.2)}',
    '.topbar{background:#1a3a5c;display:flex;align-items:stretch;min-height:64px}',
    '.topbar-logo-wrap{display:flex;align-items:stretch;flex-shrink:0}',
    '.topbar-logo{height:64px;width:auto;display:block;object-fit:contain}',
    '.topbar-left{display:flex;align-items:center;gap:10px;padding:0 14px}',
    '.topbar-divider{width:1px;height:26px;background:rgba(255,255,255,0.25)}',
    '.company-name{font-size:13px;font-weight:700;color:#fff;letter-spacing:.01em;line-height:1.2}',
    '.company-sub{font-size:8.5px;color:#93C5FD;font-weight:400;letter-spacing:.03em;margin-top:1px}',



    '.title-section{padding:20px 20px 12px;border-bottom:3px solid #1a3a5c}',
    '.title-row{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:3px}',
    '.title-meta{text-align:right}',
    '.title-date{font-size:9.5px;color:#64748B}',
    '.title-time{font-size:9px;color:#94A3B8;margin-top:1px}',
    '.title-section h1{font-size:19px;font-weight:700;color:#0F172A;letter-spacing:-0.4px;margin-bottom:3px}',
    '.title-section p{font-size:9.5px;color:#64748B}',
    '.table-wrap{padding:18px 20px 24px}',
    'table{width:100%;border-collapse:collapse}',
    'thead tr{background:#1a3a5c}',
    'th{padding:9px 10px;text-align:left;font-size:8.5px;font-weight:600;color:#fff;text-transform:uppercase;letter-spacing:.07em;white-space:nowrap}',
    'th.r{text-align:right}',
    'tbody tr{border-bottom:1px solid #E2E8F0}',
    'tbody tr:nth-child(even){background:#F1F5F9}',
    'tbody tr:nth-child(odd){background:#fff}',
    'td{padding:8px 10px;vertical-align:middle;font-size:10.5px}',
    '.n{color:#94A3B8;font-size:9.5px;text-align:center}',
    '.eid{color:#64748B;font-size:10px;font-variant-numeric:tabular-nums}',
    '.nm{font-weight:600;font-size:11px;color:#0F172A;margin-bottom:1px}',
    '.rl{font-size:8.5px;color:#94A3B8}',
    '.loc{color:#334155;font-size:10px;line-height:1.4}',
    '.sc{font-weight:600;color:#0F172A;font-size:10.5px}',
    '.dash{color:#CBD5E1}',
    '.r{text-align:right}',
    '.badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:9.5px;font-weight:600}',
    '.bH{background:#DCFCE7;color:#166534}',
    '.bM{background:#FEF9C3;color:#854D0E}',
    '.bL{background:#FEE2E2;color:#991B1B}',
    '@media print{',
    '  html,body{background:#fff}',
    '  .page{box-shadow:none;margin:0;width:100%}',
    '  @page{margin:0;size:A4 portrait}',
    '  *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}',
    '  thead{display:table-header-group}',
    '  tr{page-break-inside:avoid}',
    '}',
  ].join('\n');
  const now      = new Date();
  const dateStr  = now.toLocaleDateString('en-GB', {day:'2-digit',month:'long',year:'numeric'});
  const timeStr  = now.toLocaleTimeString('en-GB', {hour:'2-digit',minute:'2-digit'});
  const html =
    '<!DOCTYPE html><html><head><meta charset="utf-8">' +
    '<title>Workforce Report ' + fiscalYear(year) + '</title>' +
    '<style>' + css + '</style></head><body>' +
    '<div class="page">' +

    '<div class="topbar">' +
      '<div class="topbar-logo-wrap">' +
        '<img class="topbar-logo" src="' + LOGO + '" alt="DGL Logo" />' +
      '</div>' +
      '<div class="topbar-left">' +
        '<div class="topbar-divider"></div>' +
        '<div><div class="company-name">Dart Global Logistics (Pvt) Ltd</div><div class="company-sub">dartglobal.com</div></div>' +
      '</div>' +
    '</div>' +

    '<div class="title-section">' +
      '<div class="title-row">' +
        '<h1>Annual Workforce Performance Report ' + fiscalYear(year) + (countryName ? ' &mdash; ' + countryName : '') + '</h1>' +
        '<div class="title-meta"><div class="title-date">' + dateStr + '</div><div class="title-time">' + timeStr + '</div></div>' +
      '</div>' +
      '<p>' + allRows.length + ' employees &nbsp;&middot;&nbsp; Performance scores &amp; potential assessments</p>' +
    '</div>' +

    '<div class="table-wrap"><table>' +
      '<thead><tr>' +
        '<th style="width:4%">#</th>' +
        '<th style="width:8%">Emp ID</th>' +
        '<th style="width:19%">Name</th>' +
        '<th style="width:35%">Organisational Unit</th>' +
        '<th class="r" style="width:12%">' + fiscalH1(year) + '</th>' +
        '<th class="r" style="width:12%">' + fiscalH2(year - 1) + '</th>' +
        '<th class="r" style="width:10%">Potential</th>' +
      '</tr></thead>' +
      '<tbody>' + tableRows + '</tbody>' +
    '</table></div>' +

    '</div></body></html>';

    const blob = new Blob([html], { type: 'text/html' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url;
  a.download = `workforce-report-${fiscalYear(year)}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

export default function WorkforceReport() {
  const { user, loading: authLoading } = useAuth();
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear() - 1);
  const [rows,         setRows]         = useState<ReportRow[]>([]);
  const [loading,      setLoading]      = useState(false);
  const [pdfLoading,   setPdfLoading]   = useState(false);
  const [error,        setError]        = useState('');
  const [page,         setPage]         = useState(1);
  const [totalPages,   setTotalPages]   = useState(0);
  const [total,        setTotal]        = useState(0);
  const [requesterCountry, setRequesterCountry] = useState<string | null>(null);

  useEffect(() => {
    if (!user?.id) return;
    fetch(`${API}/api/rating-periods/current?user_id=${user.id}`)
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (d?.pms_year) setSelectedYear(d.pms_year); })
      .catch(() => {});
  }, [user?.id]);

  const fetchReport = useCallback(async (pageNum = 1) => {
    if (!user?.id) return;
    setLoading(true); setError('');
    try {
      const res = await fetch(`${API}/api/workforce-report?pms_year=${selectedYear}&requester_id=${user.id}&page=${pageNum}`);
      if (!res.ok) { const b = await res.json().catch(() => ({})); throw new Error((b as {error?:string}).error ?? `HTTP ${res.status}`); }
      const data: PaginatedResponse = await res.json();
      setRows(data.rows); setPage(data.page); setTotalPages(data.total_pages); setTotal(data.total);
      if (data.requester_country) setRequesterCountry(data.requester_country);
    } catch (e: unknown) { setError(e instanceof Error ? e.message : 'Failed to load.'); }
    setLoading(false);
  }, [user?.id, selectedYear]);

  useEffect(() => {
    if (!authLoading && user) { setPage(1); fetchReport(1); }
  }, [authLoading, user, fetchReport]);

  const onPdf = async () => {
    if (!user?.id) return;
    setPdfLoading(true);
    try { await handlePdfDownload(user.id, selectedYear, requesterCountry); }
    catch { setError('PDF generation failed.'); }
    setPdfLoading(false);
  };

  const th: React.CSSProperties = {
    padding:'9px 12px', textAlign:'left', fontSize:10.5, fontWeight:700, color:'#64748B',
    textTransform:'uppercase', letterSpacing:'0.06em', background:'#F8FAFC',
    borderBottom:'1px solid #E2E8F0', whiteSpace:'nowrap',
  };

  return (
    <div style={{minHeight:'100vh',background:C.pageBg,fontFamily:'Inter, system-ui, sans-serif'}}>
      <div style={{padding:'24px 32px',maxWidth:1100,margin:'0 auto'}}>

        <div style={{display:'flex',gap:6,marginBottom:16,fontSize:13,color:C.textMuted,alignItems:'center'}}>
          <Link href="/dashboard" style={{color:C.textMuted,textDecoration:'none'}}>Home</Link>
          <span>›</span>
          <span style={{color:C.textDark}}>Workforce Report</span>
        </div>

        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:24,flexWrap:'wrap',gap:12}}>
          <div>
            <h1 style={{fontSize:26,fontWeight:600,color:C.textMain,margin:'0 0 4px'}}>Workforce Performance Report</h1>
            <p style={{fontSize:14,color:C.textSub,margin:0}}>
              {fiscalYear(selectedYear)} · {user?.role === 'country_admin' ? (requesterCountry ?? 'Your country') : 'All countries'}
            </p>
          </div>
          {total > 0 && (
            <button onClick={onPdf} disabled={pdfLoading} style={{
              display:'flex',alignItems:'center',gap:6,padding:'7px 16px',borderRadius:8,
              border:'1px solid #BFDBFE',background:C.blueBg,color:C.blue,
              fontSize:13,fontWeight:600,cursor:pdfLoading?'wait':'pointer',fontFamily:'inherit',
              opacity:pdfLoading?0.7:1,
            }}>
              <Download size={13}/> {pdfLoading ? 'Preparing…' : 'Download PDF'}
            </button>
          )}
        </div>

        <div style={{background:'#fff',border:`1px solid ${C.border}`,borderRadius:8,overflow:'hidden',boxShadow:'0 1px 3px rgba(0,0,0,0.06)'}}>
          <div style={{padding:'16px 20px',borderBottom:`1px solid ${C.border}`,borderLeft:'4px solid #2563EB'}}>
            <h3 style={{margin:0,fontSize:14,fontWeight:600,color:C.textMain}}>{fiscalYear(selectedYear)} Annual Report</h3>
            <p style={{margin:'2px 0 0',fontSize:12,color:C.textMuted}}>
              {loading ? 'Loading…' : `${total} employees · sorted by country, branch, department`}
            </p>
          </div>

          {loading && <div style={{padding:'60px 24px',textAlign:'center',color:C.textMuted,fontSize:14}}>Loading…</div>}
          {!loading && error && <div style={{padding:'32px',textAlign:'center',color:'#DC2626',fontSize:13}}>{error}</div>}
          {!loading && !error && rows.length === 0 && <div style={{padding:'60px 24px',textAlign:'center',color:C.textMuted,fontSize:14}}>No data found for {fiscalYear(selectedYear)}.</div>}

          {!loading && !error && rows.length > 0 && (
            <div style={{overflowX:'auto'}}>
              <table style={{width:'100%',borderCollapse:'collapse'}}>
                <colgroup>
                  <col style={{width:'4%'}}/><col style={{width:'8%'}}/><col style={{width:'18%'}}/>
                  <col style={{width:'35%'}}/><col style={{width:'11%'}}/><col style={{width:'11%'}}/><col style={{width:'13%'}}/>
                </colgroup>
                <thead>
                  <tr>
                    <th style={th}>#</th>
                    <th style={th}>Emp ID</th>
                    <th style={th}>Name</th>
                    <th style={th}>Organisational Unit</th>
                    <th style={{...th,textAlign:'center'}}>{fiscalH1(selectedYear)}</th>
                    <th style={{...th,textAlign:'center'}}>{fiscalH2(selectedYear - 1)}</th>
                    <th style={{...th,textAlign:'center'}}>Talent Block</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row, idx) => {
                    const gi = (page - 1) * PAGE_SIZE + idx;
                    const even = gi % 2 === 0;
                    return (
                      <tr key={row.id}
                        style={{background:even?'#fff':'#FAFBFD',transition:'background 0.1s'}}
                        onMouseEnter={e=>(e.currentTarget.style.background='#F0F7FF')}
                        onMouseLeave={e=>(e.currentTarget.style.background=even?'#fff':'#FAFBFD')}>
                        <td style={{padding:'10px 12px',color:'#94A3B8',fontSize:12}}>{gi+1}</td>
                        <td style={{padding:'10px 12px',color:C.textMuted,fontSize:12,fontVariantNumeric:'tabular-nums'}}>{row.emp_id??'—'}</td>
                        <td style={{padding:'10px 12px'}}>
                          <div style={{fontWeight:600,fontSize:13,color:C.textDark}}>{row.full_name}</div>
                          <div style={{fontSize:11,color:'#94A3B8',marginTop:1}}>{formatRole(row.role)}</div>
                        </td>
                        <td style={{padding:'10px 12px',color:C.textSub,fontSize:12.5,lineHeight:1.4}}>{row.organisational_unit}</td>
                        <td style={{padding:'10px 12px',textAlign:'center'}}><Score value={row.h1_score}/></td>
                        <td style={{padding:'10px 12px',textAlign:'center'}}><Score value={row.h2_score}/></td>
                        <td style={{padding:'10px 12px',textAlign:'center'}}><TalentBadge value={row.talent_block}/></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {totalPages > 1 && (
          <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginTop:16,flexWrap:'wrap',gap:8}}>
            <span style={{fontSize:12.5,color:C.textMuted}}>
              {((page-1)*PAGE_SIZE)+1}&#8211;{Math.min(page*PAGE_SIZE,total)} of {total}
            </span>
            <div style={{display:'flex',gap:4,alignItems:'center'}}>
              <button onClick={()=>fetchReport(page-1)} disabled={page===1}
                style={{padding:'5px 12px',borderRadius:6,border:`1px solid ${C.border}`,background:'#fff',
                  color:page===1?'#CBD5E1':C.textDark,fontSize:12.5,cursor:page===1?'not-allowed':'pointer',fontFamily:'inherit'}}>
                ← Prev
              </button>
              {Array.from({length:totalPages},(_,i)=>i+1)
                .filter(p=>p===1||p===totalPages||Math.abs(p-page)<=1)
                .reduce((acc:(number|string)[],p,i,arr)=>{
                  if(i>0&&(p as number)-(arr[i-1] as number)>1) acc.push('...');
                  acc.push(p); return acc;
                },[])
                .map((p,i)=> p==='...'
                  ? <input key={`gap-${i}`} type="number" min={1} max={totalPages} placeholder="…"
                      onKeyDown={e=>{
                        if(e.key==='Enter'){
                          const v=parseInt((e.target as HTMLInputElement).value);
                          if(v>=1&&v<=totalPages){fetchReport(v);(e.target as HTMLInputElement).value='';}
                        }
                      }}
                      style={{width:44,padding:'4px 0',borderRadius:6,textAlign:'center',
                        border:`1px solid ${C.border}`,fontSize:12.5,color:C.textMuted,
                        fontFamily:'inherit',outline:'none',background:'#fff'}}
                    />
                  : <button key={p} onClick={()=>fetchReport(p as number)} style={{
                      padding:'5px 10px',borderRadius:6,
                      border:`1px solid ${p===page?C.blue:C.border}`,
                      background:p===page?C.blueBg:'#fff',
                      color:p===page?C.blue:C.textDark,
                      fontSize:12.5,fontWeight:p===page?700:400,
                      cursor:'pointer',fontFamily:'inherit'}}>{p}</button>
                )}
              <button onClick={()=>fetchReport(page+1)} disabled={page===totalPages}
                style={{padding:'5px 12px',borderRadius:6,border:`1px solid ${C.border}`,background:'#fff',
                  color:page===totalPages?'#CBD5E1':C.textDark,fontSize:12.5,
                  cursor:page===totalPages?'not-allowed':'pointer',fontFamily:'inherit'}}>
                Next →
              </button>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}